const int ldrPin = 7;
const int buzzerPin = 11;

void setup()
{
  pinMode(ldrPin, INPUT);
  pinMode(buzzerPin, OUTPUT);
  digitalWrite(buzzerPin, LOW);
}

void loop()
{
  int sensor = digitalRead(ldrPin);

  if(sensor == HIGH)
  {
    digitalWrite(buzzerPin, HIGH);
  }
  else
  {
    digitalWrite(buzzerPin, LOW);
  }

  delay(20);
}

